const $=id=>document.getElementById(id), DIRECT={delta:'https://api.india.delta.exchange',shark:'https://api.sharkexchange.in'},TF=['1h','4h','1d'],SEC={'1h':3600,'4h':14400,'1d':86400};
let listings=[],results=[],expanded=null,quote='USD',activeTab='listings',mode='scalp',loadId=0,scanId=0,coverage='',newsFlags=new Set(),marketNewsWatch=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c=quote)=>(n===null||n===undefined||n===''||!Number.isFinite(+n))?'—':`${c==='INR'?'₹':'$'}${(+n).toLocaleString('en-US',{maximumFractionDigits:+n>=100?2:+n>=1?4:8})}`;
const compact=(n,c=quote)=>(n===null||n===undefined||n===''||!Number.isFinite(+n))?'—':`${c==='INR'?'₹':'$'}${Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(+n)}`;
const pct=n=>(n===null||n===undefined||n===''||!Number.isFinite(+n))?'—':`${+n>=0?'+':''}${(+n).toFixed(2)}%`;
function exchange(){return $('exchange').value}function market(){return exchange()==='delta'?'USD':$('market').value}
let sharkPublicNext=0;
async function fetchJson(ex,path,options={}){if(ex==='shark'){let wait=Math.max(0,sharkPublicNext-Date.now());sharkPublicNext=Math.max(Date.now(),sharkPublicNext)+1200;if(wait)await new Promise(resolve=>setTimeout(resolve,wait))}let last;for(const base of (ex==='shark'?['/api/'+ex]:[DIRECT[ex],'/api/'+ex])){try{let r=await fetch(base+path,{cache:'no-store',signal:AbortSignal.timeout(15000),...options});if(!r.ok)throw Error(`HTTP ${r.status}`);return await r.json()}catch(e){last=e}}throw Error(`${ex==='delta'?'Delta India':'Shark'} feed unavailable (${last?.message||'network error'}).`)}
const unwrap=d=>d?.result??d?.data??d;
function normalized(raw,ex,tf,live=false){let a=unwrap(raw);if(!Array.isArray(a))throw Error('Candle response unavailable');let mapped=a.map(x=>({time:ex==='delta'?+x.time*1000:+x.startTime,open:+x.open,close:+x.close,high:+x.high,low:+x.low,volume:+x.volume})).filter(x=>Number.isFinite(x.time)&&x.open>0&&x.high>=x.open&&x.low<=x.open&&x.close>0&&x.high>=x.close&&x.low<=x.close&&x.low>0&&Number.isFinite(x.volume)&&x.volume>=0&&(live?x.time<=Date.now():x.time+SEC[tf]*1000<=Date.now()));let bars=[...new Map(mapped.map(x=>[x.time,x])).values()].sort((a,b)=>a.time-b.time);if(!bars.length||Date.now()-bars.at(-1).time>SEC[tf]*2000)throw Error('Candle feed is stale');for(let i=Math.max(1,bars.length-30);i<bars.length;i++)if(bars[i].time-bars[i-1].time!==SEC[tf]*1000)throw Error('Candle history has gaps');return bars}
async function fetchCandles(ex,symbol,tf,count,live=false){if(ex==='delta'){let end=Math.floor(Date.now()/1000),start=end-SEC[tf]*(count+3);return normalized(await fetchJson(ex,`/v2/history/candles?resolution=${tf}&symbol=${encodeURIComponent(symbol)}&start=${start}&end=${end}`),ex,tf,live)}return normalized(await fetchJson(ex,'/v1/market/klines?priceType=LAST_PRICE',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pair:symbol,interval:tf,limit:Math.min(1000,count+3)})}),ex,tf,live)}
const closedCandleCache=new Map();
async function candles(ex,symbol,tf,count,live=false){if(live)return fetchCandles(ex,symbol,tf,count,true);let key=[ex,symbol,tf,count,Math.floor(Date.now()/(SEC[tf]*1000))].join(':');if(!closedCandleCache.has(key)){if(closedCandleCache.size>1500)closedCandleCache.clear();closedCandleCache.set(key,fetchCandles(ex,symbol,tf,count).catch(e=>{closedCandleCache.delete(key);throw e}))}return closedCandleCache.get(key)}
function setError(message){$('error').textContent=message;$('error').classList.remove('hide')}function clearError(){$('error').classList.add('hide')}
function renderListings(){let needle=$('search').value.trim().toUpperCase(),shown=listings.filter(x=>x.symbol.includes(needle)||x.base.includes(needle));$('listingCount').textContent=`${listings.length}`;$('listingStatus').textContent=`${shown.length} of ${listings.length} listed contracts`;$('listingRows').innerHTML=shown.length?shown.map(x=>`<tr><td class="coin"><button class="coin-link" data-chart="${esc(x.symbol)}">${esc(x.base)}</button><small>${esc(x.symbol)}</small></td><td>${money(x.price,x.quote)}</td><td>${compact(x.volume,x.quote)}</td><td class="${x.change>=0?'positive':'negative'}">${pct(x.change)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No contracts match your search.</td></tr>'}
async function loadListings(){let id=++loadId;scanId++;resetChart();$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market';$('progress').classList.add('hide');$('coverage').textContent='';let ex=exchange(),q=market();quote=q;clearError();listings=[];results=[];$('listingCount').textContent='';$('listingStatus').textContent='Loading exchange listings…';$('listingRows').innerHTML='<tr><td colspan="4" class="empty">Loading listings…</td></tr>';$('rows').innerHTML='<tr><td colspan="8" class="empty">Run the scan for this exchange.</td></tr>';$('market').closest('.control').classList.toggle('hide',ex!=='shark');$('updated').textContent='Loading '+(ex==='delta'?'Delta India':'Shark');try{let loaded;if(ex==='delta'){let d=unwrap(await fetchJson('delta','/v2/tickers?contract_types=perpetual_futures'));if(!Array.isArray(d))throw Error('The ticker list was empty');loaded=d.filter(x=>x.contract_type==='perpetual_futures'&&/USD$/.test(x.symbol)).map(x=>({symbol:x.symbol,base:x.symbol.replace(/USD$/,''),quote:'USD',price:+x.close,volume:+x.turnover_usd,change:+x.ltp_change_24h,exchange:ex})).sort((a,b)=>(b.volume||0)-(a.volume||0))}else{let d=unwrap(await fetchJson('shark',`/v1/exchange/exchangeInfo?market=${q}`));let contracts=Array.isArray(d)?d:(d?.contracts??d?.market?.flatMap?.(m=>m.contracts??[])??d?.markets?.flatMap?.(m=>m.contracts??[])??[]);if(contracts.length&&contracts[0]?.contracts)contracts=contracts.flatMap(m=>m.contracts??[]);if(!contracts.length)throw Error('The contract list was empty');loaded=[...new Map(contracts.filter(c=>typeof(c.name??c.symbol)==='string'&&(c.name??c.symbol).endsWith(q)&&(c.contractType??'PERPETUAL')==='PERPETUAL').map(c=>{let symbol=c.name??c.symbol;return [symbol,{symbol,base:c.baseAsset??symbol.slice(0,-q.length),quote:q,price:null,volume:null,change:null,exchange:ex,rawContract:c}]})).values()].sort((a,b)=>a.symbol.localeCompare(b.symbol))}if(id!==loadId)return;listings=loaded;if(!listings.length)throw Error('No perpetual contracts returned');renderListings();syncChartCoins();syncTicketCoins();if(!chartData&&activeTab==='chart')openChart($('chartCoin').value,mode);loadAlertProfile();if($('autoScan').checked&&!$('runStrategy').disabled)runStrategy();$('updated').textContent='Listings updated '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('dataNote').textContent=ex==='delta'?'Delta India USD perpetuals. Price and turnover from its ticker feed.':`Shark ${q} perpetuals. Prices and turnover load when you run the strategy scan.`}catch(e){if(id!==loadId)return;setError(`${e.message} Check your connection or tap Refresh.`);$('listingStatus').textContent='Listings unavailable';$('listingRows').innerHTML='<tr><td colspan="4" class="empty"><strong>Listings could not load.</strong>Refresh to retry.</td></tr>';$('updated').textContent='Feed unavailable'}}
async function fillSharkTickers(id){let pool=listings.slice(),next=0,done=0;async function worker(){while(next<pool.length&&id===scanId){let t=pool[next++];try{let d=unwrap(await fetchJson('shark',`/v1/market/ticker24Hr/${encodeURIComponent(t.symbol)}`));if(d&&+d.c>0){t.price=+d.c;t.volume=+d.q;t.change=+d.P}}catch(e){}if(id!==scanId)return;done++;$('updated').textContent=`Loading turnover ${done}/${pool.length}`}}await Promise.all(Array.from({length:8},worker));if(id===scanId)renderListings()}
async function dailyContext(t){try{return {bars:await candles(t.exchange,t.symbol,'1d',997),error:null}}catch(e){return {bars:[],error:e.message}}}
async function scanPair(t){let [h,f,context]=await Promise.all([candles(t.exchange,t.symbol,'1h',75),candles(t.exchange,t.symbol,'4h',330),dailyContext(t)]);return {...t,price:t.price??h.at(-1).close,...StrategySignals.evaluate(h,f,context.bars),dailyError:context.error,plans:Object.fromEntries(['breakout','ema','scalp','cross'].map(m=>[m,StrategySignals.plan(h,f,m,context.bars)]))}}
const descriptions={scalp:'<strong>1 · 1H High-volume Breakout</strong>A completed 1H candle breaks its previous 20-bar range with at least 2× average volume. Both upward and downward breaks qualify. Strong closes only; moves more than 1% beyond the level are excluded.',breakout:'<strong>2 · Multi-timeframe / ATH Watch</strong>Aligns 1H, 4H, daily, weekly and monthly highs. Price must be within 2% of the loaded historical high, with 2× 1H and 1.5× 4H volume. A completed 1H close above every level and a 4H close above its range confirms the breakout. Up to 1,000 daily candles are checked; the displayed history high is not a verified lifetime ATH. Coins with insufficient history cannot qualify.',ema:'<strong>3 · 4H 200 EMA Consolidation</strong>Finds a 12-candle range no wider than 5%, close to the 200 EMA. Range-top setups watch for a breakout; range-bottom setups watch for a breakdown. A completed 1H close outside the range confirms the entry.',cross:'<strong>4 · Golden Cross / Death Cross</strong>A new 50 SMA / 200 SMA cross on a completed 4H candle, with at least 1.2× normal volume. Golden cross watches long entries; death cross watches short entries. Entry plans expire one hour after confirmation.'};
function explainMode(){$('strategyExplain').innerHTML=descriptions[mode];document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('strategyHead').innerHTML='<tr><th>Coin</th><th>Setup</th><th>'+ (mode==='ema'?'200 EMA':'Level to watch')+'</th><th>Volume vs usual</th><th>Why it appears</th></tr>'}
function renderStrategy(){let shown=results.filter(r=>(+$('minVolume').value===0||r.volume>=+$('minVolume').value)&&r[mode].match).sort((a,b)=>b.volume-a.volume);$('count').textContent=results.length;$('near').textContent=shown.length;$('breakouts').textContent=shown.filter(r=>r.scalp.match).length;$('highest').textContent=shown.length?compact(Math.max(...shown.map(r=>r.volume))):'—';$('quoteLabel').textContent=quote+' turnover';$('rows').innerHTML=shown.length?shown.map(r=>{let x=r[mode];return `<tr data-symbol="${esc(r.symbol)}" tabindex="0" aria-expanded="${expanded===r.symbol}"><td class="coin">${esc(r.base)}<small>${esc(r.symbol)}</small></td><td><span class="pill near">${x.label}</span></td><td>${money(x.level)}</td><td>${x.volume.toFixed(2)}×</td><td>${esc(x.why)}${marketNewsWatch||newsFlags.has(r.base.toUpperCase())?'<small class="risk-tag">Review news risk</small>':''}<button class="chart-link" data-chart="${esc(r.symbol)}">Chart &amp; plan ↗</button><small class="muted">Details ↓</small></td></tr>${expanded===r.symbol?`<tr class="details"><td colspan="5"><div class="detail-grid"><div class="detail-card"><b>Every rule passed</b>${x.checks.map(c=>`<span>✓ ${esc(c.name)}</span>`).join('')}</div><div class="detail-card"><b>Price context</b><span>Latest ticker: ${money(r.price)}</span><span>24h turnover: ${compact(r.volume)}</span>${mode==='ema'?`<span>Range bottom: ${money(x.low)}</span><span>Range top: ${money(x.high)}</span><span>4h close to EMA: ${pct(x.distance)}</span>`:''}<span>Signal candle closed: ${new Date(x.time+SEC[x.tf]*1000).toLocaleString()}</span></div><div class="detail-card"><b>Before a trade</b><span>These are rule matches, not a win probability. Check the current price, spread and news. A failed breakout can still occur.</span></div></div></td></tr>`:''}`}).join(''):`<tr><td colspan="5" class="empty"><strong>${results.length?'No coins match all rules.':'Choose a scan, then tap Scan market.'}</strong>${results.length?'No forced signals. Try again after the next candle closes.':'One scan checks all four strategies.'}</td></tr>`}
async function runStrategy(){let id=++scanId,ex=exchange();if(!listings.length){setError('Load the listings first, then run the scan.');return}clearError();$('runStrategy').disabled=true;$('runStrategy').textContent='Scanning…';$('progress').classList.remove('hide');$('progressBar').style.width='2%';$('rows').innerHTML='<tr><td colspan="8" class="empty">Calculating closed-candle signals…</td></tr>';try{if(ex==='shark')await fillSharkTickers(id);else{let fresh=unwrap(await fetchJson('delta','/v2/tickers?contract_types=perpetual_futures'));if(!Array.isArray(fresh))throw Error('Liquidity feed unavailable');let bySymbol=new Map(fresh.map(x=>[x.symbol,x]));for(let t of listings){let x=bySymbol.get(t.symbol);t.volume=x?+x.turnover_usd:0;if(x)t.price=+x.close}}if(id!==scanId)return;let candidates=listings.filter(x=>+$('minVolume').value===0||x.volume>=+$('minVolume').value).sort((a,b)=>b.volume-a.volume);if(!candidates.length)throw Error('No contracts meet this turnover filter. Try a lower minimum.');let next=0,done=0,out=[],failed=0;async function worker(){while(next<candidates.length&&id===scanId){let t=candidates[next++];try{out.push(await scanPair(t))}catch(e){failed++}if(id!==scanId)return;done++;$('progressBar').style.width=Math.round(done/candidates.length*100)+'%';$('updated').textContent=`Scanning ${done}/${candidates.length}`}}await Promise.all(Array.from({length:5},worker));if(id!==scanId)return;if(!out.length)throw Error('Candle history is unavailable for these contracts');results=out;expanded=null;renderStrategy();for(let t of out)for(let m of ['breakout','ema','scalp','cross']){let z=t[m];if(z?.match&&Date.now()-(z.time+SEC[z.tf]*1000)<SEC[z.tf]*1000)await alertSetup(t,m);}coverage=`Checked ${out.length}/${candidates.length} eligible contracts from ${listings.length} listings. ${out.filter(t=>t.dailyError).length} lack daily context for MTF. ${failed} excluded for missing, stale or insufficient candles. Closed candles only. Refresh by scanning again.`;$('coverage').textContent=coverage;$('updated').textContent='Scan updated '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(failed)setError(`${failed} contracts could not be scanned and were excluded.`)}catch(e){if(id===scanId){setError(e.message);$('rows').innerHTML='<tr><td colspan="8" class="empty">Strategy data unavailable. Try again.</td></tr>'}}finally{if(id===scanId){$('progress').classList.add('hide');$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market'}}}
async function loadNews(){try{let key=$('cmcKey').value.trim();$('cmcKey').value='';let options=key?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key}),cache:'no-store'}:{cache:'no-store'};let r=await fetch('/api/news',options),d=await r.json();if(!d.configured){$('newsStatus').textContent='News risk unverified: a CoinMarketCap Growth, Professional or Enterprise API key is needed for automated headlines. Open the latest news link before a trade.';return}if(!r.ok||d.error)throw Error(d.error||'News unavailable');let recent=d.articles.filter(x=>Date.now()-new Date(x.at).getTime()<48*3600000),risk=/\b(hack|exploit|breach|attack|lawsuit|delist|ban|liquidation|outage|war|sanction|fed|interest rate|regulator|sec|etf decision)\b/i;let flagged=recent.filter(x=>risk.test(x.title));newsFlags=new Set(flagged.flatMap(x=>x.assets||[]).map(x=>String(x).toUpperCase()));marketNewsWatch=flagged.some(x=>/\b(fed|interest rate|war|sanction|liquidation)\b/i.test(x.title));renderStrategy();$('newsStatus').textContent=`${recent.length} CMC headlines in the last 48h · ${flagged.length} keyword flags for review. A flag is not a verified market impact; no headlines does not mean low risk.`;$('newsRows').innerHTML=recent.slice(0,8).map(x=>{let safe=/^https:\/\//.test(x.url)?x.url:'https://coinmarketcap.com/headlines/news/';return `<div class="news-item"><a href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a><small>${new Date(x.at).toLocaleString()}${x.assets?.length?' · '+esc(x.assets.join(', ')):''}</small>${risk.test(x.title)?'<span class="risk-tag">Review catalyst</span>':''}</div>`}).join('')}catch(e){$('newsStatus').textContent='News risk unverified: CoinMarketCap feed unavailable. Review the latest news link before a trade.'}}
function tab(name){activeTab=name;for(let key of ['listings','strategy','chart','api']){$(key+'View').classList.toggle('hide',key!==name);let b=document.querySelector(`[data-tab="${key}"]`);b.classList.toggle('active',key===name);if(key===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{tab(b.dataset.tab);if(b.dataset.tab==='chart'&&!chartData&&listings.length)loadChart()}));$('exchange').addEventListener('change',loadListings);$('market').addEventListener('change',loadListings);$('refresh').addEventListener('click',loadListings);$('search').addEventListener('input',renderListings);$('runStrategy').addEventListener('click',runStrategy);$('checkNews').addEventListener('click',loadNews);$('minVolume').addEventListener('change',()=>{scanId++;$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market';$('progress').classList.add('hide');results=[];renderStrategy();$('coverage').textContent='Filter changed. Scan again to check all eligible coins.'});document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;expanded=null;explainMode();renderStrategy()}));$('rows').addEventListener('click',e=>{let btn=e.target.closest('[data-chart]');if(btn){openChart(btn.dataset.chart,mode);return}let tr=e.target.closest('tr[data-symbol]');if(tr){expanded=expanded===tr.dataset.symbol?null:tr.dataset.symbol;renderStrategy()}});$('rows').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-symbol]')){e.preventDefault();expanded=expanded===e.target.dataset.symbol?null:e.target.dataset.symbol;renderStrategy()}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_market_view',title:'Select market view',description:'Show listings or the strategy for the selected exchange.',inputSchema:{type:'object',properties:{exchange:{type:'string',enum:['delta','shark']},view:{type:'string',enum:['listings','strategy','chart','api']}},required:['exchange','view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['delta','shark'].includes(input?.exchange)||!['listings','strategy','chart','api'].includes(input?.view))throw Error('Invalid view');if($('exchange').value!==input.exchange){$('exchange').value=input.exchange;loadListings()}tab(input.view);return {exchange:input.exchange,view:input.view}}})).catch(()=>{})}catch(e){}}


