async function loadChart(){let t=listings.find(t=>t.symbol===$('chartCoin').value);if(!t)return;stopLive();if(tvChart){tvChart.remove();tvChart=null;tvCandles=null;}let id=++chartId;historyId++;chartData=null;$('testHistory').disabled=true;$('loadChart').disabled=true;$('chartTitle').textContent=t.symbol;mountAdvancedChart(t);$('chartStatus').textContent='Loading exchange candles…';$('priceChart').innerHTML='<div class="empty">Loading chart…</div>';$('planSummary').textContent='Checking this setup…';$('riskResult').textContent='Checking the plan…';$('historyResult').textContent='No test run yet. No win probability has been assumed.';try{let [allH,allF,contract,context]=await Promise.all([candles(t.exchange,t.symbol,'1h',150,true),candles(t.exchange,t.symbol,'4h',330,true),loadContract(t),dailyContext(t)]);if(id!==chartId)return;let h=allH.filter(c=>c.time+3600000<=Date.now()),f=allF.filter(c=>c.time+14400000<=Date.now());chartData={t,h,f,d:context.bars,dailyError:context.error,allH,allF,rules:contract,mode:$('chartMode').value};$('manualEntry').value=allH.at(-1).close;$('manualStop').value='';$('manualTarget').value='';setLeverage();renderChart();$('testHistory').disabled=!contract;startLive();}catch(e){if(id!==chartId)return;$('chartStatus').textContent=e.message;$('priceChart').innerHTML='<div class="empty">Chart unavailable. Tap Load chart to retry.</div>';$('planSummary').textContent='No plan: candle data is unavailable.';$('riskResult').textContent='No sizing available without a valid plan.'}finally{if(id===chartId)$('loadChart').disabled=false}}
function fmtPrice(n){return Number(n).toLocaleString('en-US',{maximumFractionDigits:n>=100?2:n>=1?4:8})}
function drawTradingView(bars,p,emas,tf){if(tvChart)tvChart.remove();$('priceChart').innerHTML='';if(!window.LightweightCharts)throw Error('TradingView chart engine could not load. Refresh this page.');const L=window.LightweightCharts;tvChart=L.createChart($('priceChart'),{autoSize:true,height:430,layout:{background:{type:'solid',color:'#ffffff'},textColor:'#496171',attributionLogo:true},grid:{vertLines:{color:'#f0f3f6'},horzLines:{color:'#edf2f5'}},timeScale:{timeVisible:true,secondsVisible:false},localization:{timeFormatter:t=>new Date(t*1000).toLocaleString()},rightPriceScale:{scaleMargins:{top:.12,bottom:.12}}});tvCandles=tvChart.addSeries(L.CandlestickSeries,{upColor:'#23866b',downColor:'#d05e6a',borderVisible:false,wickUpColor:'#23866b',wickDownColor:'#d05e6a',priceFormat:{type:'custom',formatter:fmtPrice,minMove:10**(-Math.max(2,chartData.t.pricePrecision??8))},autoscaleInfoProvider:base=>{let info=base();if(info&&p){info.priceRange.minValue=Math.min(info.priceRange.minValue,p.stop,p.target);info.priceRange.maxValue=Math.max(info.priceRange.maxValue,p.stop,p.target)}return info}});tvCandles.setData(bars.map(c=>({time:c.time/1000,open:c.open,high:c.high,low:c.low,close:c.close})));let line=tvChart.addSeries(L.LineSeries,{color:'#9461b9',lineWidth:2,priceLineVisible:false,lastValueVisible:false});line.setData(emas.map((e,i)=>e===null?null:{time:bars[i].time/1000,value:e}).filter(Boolean));if(chartData.mode==='cross'){let fast=tvChart.addSeries(L.LineSeries,{color:'#d69829',lineWidth:2,priceLineVisible:false,lastValueVisible:false});fast.setData(bars.map((c,i)=>i<49?null:{time:c.time/1000,value:bars.slice(i-49,i+1).reduce((n,x)=>n+x.close,0)/50}).filter(Boolean))}drawStrategyLevels(bars,tf);if(p)for(let [title,price,color] of [['Entry',p.entry,'#1767cb'],['Stop',p.stop,'#bd424b'],['Target',p.target,'#1f8164']])tvCandles.createPriceLine({price,color,lineWidth:2,lineStyle:2,axisLabelVisible:true,title});tvChart.timeScale().setVisibleLogicalRange({from:Math.max(0,bars.length-+$('chartZoom').value),to:bars.length+3});tvLiveBar=bars.at(-1);tvChart.subscribeCrosshairMove(e=>{let c=e.seriesData?.get(tvCandles);if(c)$('candleReadout').textContent=`O ${fmtPrice(c.open)} · H ${fmtPrice(c.high)} · L ${fmtPrice(c.low)} · C ${fmtPrice(c.close)}`})}
function drawStrategyLevels(bars,tf){let {h,f,d,mode:m}=chartData,x=StrategySignals.evaluate(h,f,d)[m],lines=[];if(m==='scalp'){let prior=h.slice(-21,-1);lines=[['1H range high',Math.max(...prior.map(c=>c.high)),'#677b91'],['1H range low',Math.min(...prior.map(c=>c.low)),'#677b91']]}else if(m==='ema'){lines=[['Consolidation high',x.high,'#677b91'],['Consolidation low',x.low,'#677b91']]}else if(m==='breakout'){lines=[...(x.levels??[]).filter(l=>l.ok).map(l=>[l.name+' high',l.value,'#677b91']),['History high · ATH unverified',x.high,'#9461b9']]}for(let [title,price,color] of lines)if(Number.isFinite(price)&&price>0)tvCandles.createPriceLine({price,color,lineWidth:1,lineStyle:2,axisLabelVisible:true,title});let v=tvVolume=tvChart.addSeries(LightweightCharts.HistogramSeries,{priceFormat:{type:'volume'},priceScaleId:'volume'});v.priceScale().applyOptions({scaleMargins:{top:.85,bottom:0}});v.setData(bars.map(c=>({time:c.time/1000,value:c.volume,color:c.close>=c.open?'#23866b45':'#d05e6a45'})));}
function renderChart(){if(!chartData)return;let {h,f,t}=chartData,m=$('chartMode').value;chartData.mode=m;let p=$('planMode').value==='manual'?manualPlan():StrategySignals.plan(h,f,m,chartData.d);chartData.plan=p;let bars=m==='scalp'?(chartData.allH??h):(chartData.allF??f).slice(-330),tf=m==='scalp'?'1h':'4h',emas=bars.map(()=>null);if(m==='cross'&&bars.length>=200){emas=bars.map((c,i)=>i<199?null:bars.slice(i-199,i+1).reduce((n,x)=>n+x.close,0)/200)}else if(m!=='scalp'&&bars.length>=220){let e=bars.slice(0,200).reduce((s,c)=>s+c.close,0)/200;emas[199]=e;for(let i=200;i<bars.length;i++){e+=(bars[i].close-e)*2/201;emas[i]=e}}$('chartTitle').textContent=`${t.symbol} · ${tf}`;$('chartStatus').textContent=`Signal candle closed ${new Date((m==='scalp'?h:f).at(-1).time+SEC[tf]*1000).toLocaleString()} · Prices in ${t.quote}`;drawTradingView(bars,p,emas,tf);drawAccountLines();$('maLegend').textContent=m==='cross'?'— 200 SMA (purple) / 50 SMA (gold)':m==='scalp'?'— 1H range and volume':m==='breakout'?'— Multi-timeframe highs / historical high':'— 200 EMA and consolidation range';$('trackSetup').disabled=!p; if(p)announceSetup(chartData);
if(!p&&$('planMode').value==='manual'){$('planSummary').innerHTML='<h3>Enter your trade prices above</h3><p>For a long: stop &lt; entry &lt; target. For a short: target &lt; entry &lt; stop. This calculator works for any listed coin.</p>'}else if(!p){let match=StrategySignals.evaluate(h,f,chartData.d)[m].match;if(m==='cross')match=false;$('planSummary').innerHTML=`<h3>${match?'Wait for the range edge':'No qualifying entry right now'}</h3><p>${match?'The coin is consolidating in the middle of its range. Wait for it to reach the top or bottom before planning a breakout.':'This coin does not pass every rule for this strategy. No trade is suggested.'}</p>${StrategySignals.evaluate(h,f,chartData.d)[m].checks.map(c=>`<div class="check ${c.ok?'good':''}"><span>${esc(c.name)}</span><b>${c.ok?'Pass':'Waiting'}</b></div>`).join('')}${m==='breakout'?'<p class="small-note">Historical high uses '+(chartData.d?.length??0)+' loaded daily candles. Lifetime ATH is unverified.</p>':''}`}else{$('planSummary').innerHTML=`<h3>${p.manual?'Manual':p.side===1?'Long':'Short'} plan · ${p.manual?'your entry levels':p.confirmed?'signal close confirmed':'wait for confirmation'}</h3><p>${p.manual?'Your manually entered prices. No strategy confirmation is assumed.':p.confirmed?'Entry is a reference from the latest closed candle. Recheck the current price before trading.':`Wait for a 1h candle to close ${p.side===1?'above':'below'} ${money(p.trigger,t.quote)}. The setup expires after 12 hours without confirmation.`} Target reward/risk: ${((p.side*(p.target-p.entry))/p.risk).toFixed(2)}R before costs.</p><div class="plan-levels"><div><span>${p.confirmed?'Reference entry':'Entry trigger'}</span><b>${money(p.entry,t.quote)}</b></div><div><span>Stop loss</span><b>${money(p.stop,t.quote)}</b></div><div><span>Target · 2R</span><b>${money(p.target,t.quote)}</b></div></div>`}renderRisk()}
function renderRisk(){let p=chartData?.plan,b=+$('balance').value,r=+$('riskPercent').value,c=+$('costPercent').value;if(!p){$('riskResult').textContent='Enter entry, stop and target prices above, or choose a qualifying strategy.';return}if(!$('balance').value){$('riskResult').textContent=`Enter your balance in ${chartData.t.quote} to calculate position size and leverage.`;return}if(!chartData.rules){$('riskResult').textContent='Leverage limits unavailable. Reload chart to retry.';return}let v=StrategySignals.size(p,b,r,c,+$('leverage').value,chartData.rules);chartData.sizing=v;if(!v||$('costPercent').value===''){$('riskResult').textContent='Check your balance, leverage and costs. The size must meet the contract minimum.';return}if(v){v.targetProfit=v.units*(p.side*(p.target-p.entry))-v.notional*c/100;}if(v.targetProfit<=0){$('riskResult').textContent='Skip this setup: estimated costs erase the target profit. Check your fee and slippage inputs.';return}let q=chartData.t.quote;$('riskResult').innerHTML=`<div class="risk-metrics"><div><span>Planned loss, including costs</span><strong>${money(v.loss,q)}</strong></div><div><span>Selected leverage</span><strong>${v.leverage}× isolated</strong></div><div><span>Position value</span><strong>${money(v.notional,q)}</strong></div><div><span>Estimated margin</span><strong>${money(v.margin,q)}</strong></div></div><p class="risk-tag">${v.unsafe?'Estimated liquidation is before the stop: lower leverage.':''}</p><p>Estimated liquidation: ${money(v.liquidation,q)} (approximate).</p><p>Stop distance: ${(p.risk/p.entry*100).toFixed(2)}% · Approx. ${v.units.toLocaleString('en-US',{maximumSignificantDigits:5})} ${esc(chartData.t.base)} exposure.</p><p>Net target estimate: ${money(v.targetProfit,q)}${v.targetProfit<=0?' — costs erase the target; skip this setup.':'.'} ${v.capped?'Position reduced to fit the 25% margin budget and exchange contract limits.':''}</p><p class="small-note">Exposure is not a contract count. Round down using the exchange’s contract size. Confirm the exchange permits this leverage. Selected leverage does not guarantee protection from liquidation.</p>`}
async function testHistory(){if(!chartData)return;let id=++historyId,base=chartData,m=base.mode,cost=+$('costPercent').value;let settings={daily:base.d,balance:+$('balance').value,risk:+$('riskPercent').value,leverage:+$('leverage').value,rules:base.rules};if(!(settings.balance>0)||!settings.rules){$('historyResult').textContent='Enter your balance and load exchange leverage limits first.';return}if(!Number.isFinite(cost)||cost<0||cost>5||$('costPercent').value===''){$('historyResult').textContent='Enter costs between 0% and 5% first.';return}$('testHistory').disabled=true;$('testHistory').textContent='Testing…';$('historyResult').textContent='Loading past candles and replaying the rules…';try{if(!base.historyBars){let [h,f]=await Promise.all([candles(base.t.exchange,base.t.symbol,'1h',997),candles(base.t.exchange,base.t.symbol,'4h',997)]);if(id!==historyId||chartData!==base)return;base.historyBars={h,f}}let {h,f}=base.historyBars,result=StrategySignals.backtest(h,f,m,cost,settings);if(id!==historyId||chartData!==base)return;let span=result.from&&result.to?`${new Date(result.from).toLocaleDateString()}–${new Date(result.to).toLocaleDateString()}`:'Not enough overlapping history',headline=result.n>=30?`${(result.rate*100).toFixed(0)}% historical wins`:'Not enough data for a probability';$('historyResult').innerHTML=`<div class="${result.n>=30?'history-rate':''}"><strong>${headline}</strong></div><p><strong>${settings.leverage}× simulation · Net P&amp;L ${money(result.pnl,base.t.quote)}</strong><br>Ending balance ${money(result.equity,base.t.quote)} · Max drawdown ${(result.maxDrawdown*100).toFixed(2)}% · ${result.liquidations} estimated liquidations.</p><p>${result.wins} wins / ${result.n} completed trades · ${result.losses} losses or flat results.</p>${result.n>=30?`<p>95% statistical interval: ${(result.interval[0]*100).toFixed(0)}–${(result.interval[1]*100).toFixed(0)}%. This is sampling uncertainty, not validated odds for the next trade.</p>`:'<p>At least 30 completed trades are needed to show a percentage.</p>'}<p>${result.n?`Average net result: ${result.meanR.toFixed(2)}R per trade. `:''}${cost.toFixed(2)}% estimated round-trip costs; funding excluded.</p><p class="small-note">${span}. ${h.length} 1h candles loaded. ${result.skipped} expired, incomplete, gapped or missing-history cases skipped. Patterns only; the current turnover filter and news are not replayed.</p>${result.n?`<details><summary>Recent test trades</summary><table><thead><tr><th>Entry date</th><th>Exit</th><th>Net R</th></tr></thead><tbody>${result.trades.slice(-8).reverse().map(t=>`<tr><td>${new Date(t.time).toLocaleDateString()}</td><td>${t.reason==='time'?'Time limit':t.reason==='stop'?'Stop':t.reason==='liquidation'?'Liquidation estimate':'Target'}</td><td>${t.net.toFixed(2)}R</td></tr>`).join('')}</tbody></table></details>`:''}`}catch(e){if(id===historyId)$('historyResult').textContent='Historical test unavailable: '+e.message}finally{if(id===historyId){$('testHistory').disabled=false;$('testHistory').textContent='Test historical win rate'}}}
$('listingRows').addEventListener('click',e=>{let b=e.target.closest('[data-chart]');if(b)openChart(b.dataset.chart)});$('loadChart').addEventListener('click',loadChart);$('chartCoin').addEventListener('change',loadChart);$('chartMode').addEventListener('change',()=>{historyId++;$('historyResult').textContent='Strategy changed. Run a new historical test.';$('testHistory').textContent='Test historical win rate';$('testHistory').disabled=!chartData?.rules;if(chartData){$('planMode').value='strategy';mountAdvancedChart(chartData.t);renderChart();startLive()}});$('chartZoom').addEventListener('change',renderChart);$('balance').addEventListener('input',renderRisk);$('riskPercent').addEventListener('change',renderRisk);$('costPercent').addEventListener('input',()=>{historyId++;renderRisk();$('historyResult').textContent='Costs changed. Run the test again.';$('testHistory').disabled=!chartData;$('testHistory').textContent='Test historical win rate'});$('testHistory').addEventListener('click',testHistory);


async function loadContract(t){try{let raw=t.exchange==='delta'?unwrap(await fetchJson('delta','/v2/products/'+encodeURIComponent(t.symbol))):t.rawContract;return StrategySignals.rules(raw,t.exchange)}catch(e){return null}}
function setLeverage(){let r=chartData?.rules;$('leverage').disabled=!r;$('leverage').innerHTML=r?r.choices.map(n=>`<option value="${n}">${n}×</option>`).join(''):'<option value="">Unavailable</option>';$('leverage').value=r?'1':'';$('leverageNote').textContent=r?`Current contract maximum: ${r.max}×. ${r.exchange==='delta'?'Base-tier notional cap: '+compact(r.maxNotional,chartData.t.quote)+'. ':''}Limits checked ${new Date().toLocaleTimeString()}.`:'Contract limits unavailable. Reload to retry.';if(r)$('costPercent').value=Math.max(.2,r.fee*2+.05).toFixed(2)}
function invalidateHistory(){historyId++;$('historyResult').textContent='Settings changed. Run the leveraged backtest again.';$('testHistory').textContent='Test leveraged backtest';$('testHistory').disabled=!chartData?.rules}
$('leverage').addEventListener('change',()=>{renderRisk();invalidateHistory()});$('balance').addEventListener('input',invalidateHistory);$('riskPercent').addEventListener('change',invalidateHistory);
let liveSockets=[],liveGeneration=0,receivedAt=0,lastSourceAt=0,liveSource='',fallbackBusy=false,closedBusy=false,alerts=[],seenAlerts=new Set(),tracked=[],notifyEnabled=window.Notification?.permission==='granted';
try{alerts=JSON.parse(localStorage.getItem('radarAlerts')||'[]').slice(0,30);seenAlerts=new Set(JSON.parse(localStorage.getItem('radarSeenAlerts')||'[]').slice(-300))}catch{}
try{tracked=JSON.parse(localStorage.getItem('radarTrackedEntries')||'[]').filter(t=>['delta','shark'].includes(t.exchange)&&t.symbol&&t.entry>0&&t.stop>0).slice(0,5)}catch(e){}
function saveTracked(){try{localStorage.setItem('radarTrackedEntries',JSON.stringify(tracked))}catch(e){}renderTracked()}
function renderAlerts(){$('alertRows').innerHTML=alerts.length?alerts.map(a=>`<div class="account-item"><b>${esc(a.title)}</b><p>${esc(a.message)}</p><small>${new Date(a.time).toLocaleString()}</small>${a.meta?`<button class="chart-link" data-alert-coin="${esc(a.meta.symbol)}" data-alert-ex="${esc(a.meta.exchange)}" data-alert-mode="${esc(a.meta.mode)}">Open trade plan</button>`:''}</div>`).join(''):'No setup alerts yet. Start a scan below.';let badge=$('alertCount');if(badge)badge.textContent=alerts.length?String(alerts.length):''}
function alertUser(key,title,message,meta=null){if(seenAlerts.has(key))return;seenAlerts.add(key);alerts.unshift({title,message,time:Date.now(),meta});alerts=alerts.slice(0,30);try{localStorage.setItem('radarAlerts',JSON.stringify(alerts));localStorage.setItem('radarSeenAlerts',JSON.stringify([...seenAlerts].slice(-300)))}catch{}renderAlerts();if(notifyEnabled&&window.Notification?.permission==='granted')try{new Notification(title,{body:message,tag:key})}catch{$('alertStatus').textContent='In-page alerts active; browser notification could not be delivered.'}}
async function alertSetup(t,m){let z=t[m],p=t.plans?.[m],key=`scan:${t.exchange}:${t.symbol}:${m}:${z.time}`;if(seenAlerts.has(key))return;let q=t.quote,profile=readAlertProfile(t.exchange,q),message=p?`${p.confirmed?'Setup confirmed':'Forming setup — wait for a candle close beyond the trigger'}. Entry ${money(p.entry,q)}, stop ${money(p.stop,q)}, target ${money(p.target,q)}. `:'Watch the consolidation; there is no directional entry yet. ';if(p&&profile.balance>0){try{let rules=await loadContract(t),v=rules?StrategySignals.size(p,profile.balance,profile.risk,profile.cost,null,rules):null;message+=v&&!v.unsafe&&v.targetProfit>0?`Planned loss ${money(v.loss,q)} within ${profile.risk}% risk; size ${v.units.toPrecision(5)} ${t.base}; margin ${money(v.margin,q)} at ${v.leverage}×. Costs estimated at ${profile.cost}%; gaps can exceed this loss. `:'Size unavailable or risk limits not met — skip until reviewed. '}catch{message+='Contract limits unavailable — sizing not verified. '}}else message+='Set your balance below to receive a money-risk calculation. ';message+=marketNewsWatch||newsFlags.has(t.base)?'News risk flagged; review before entry.':'Check current price, spread and news before entry.';alertUser(key,`${t.symbol} · ${z.label}`,message,{symbol:t.symbol,exchange:t.exchange,mode:m})}

function announceSetup(data){let states=StrategySignals.evaluate(data.h,data.f),z=states[data.mode];if(z.match&&Date.now()-(z.time+SEC[z.tf]*1000)<SEC[z.tf]*1000)alertSetup({...data.t,...states,plans:{[data.mode]:StrategySignals.plan(data.h,data.f,data.mode)}},data.mode).catch(()=>{})}
function renderTracked(){$('trackedRows').innerHTML=tracked.length?tracked.map((t,i)=>`<div class="account-item"><b>${esc(t.symbol)} · ${t.side===1?'Long':'Short'} · ${esc(t.mode)}</b><p>Entry ${money(t.entry,t.quote)} · Stop ${money(t.stop,t.quote)} · Target ${money(t.target,t.quote)}</p><p>${esc(t.status||'Waiting for live prices')} ${t.updated?' · '+new Date(t.updated).toLocaleTimeString():''}</p><button class="chart-link" data-remove-track="${i}">Stop tracking</button></div>`).join(''):'<p class="muted">Open a qualifying setup, enter your actual entry price and tap Track my entry. Tracking is manual; no exchange order is placed.</p>'}
function checkTracked(ex,symbol,price,at){for(let t of tracked.filter(t=>t.exchange===ex&&t.symbol===symbol)){if(at<(t.sourceAt??0))continue;t.sourceAt=at;t.updated=Date.now();let stop=t.side===1?price<=t.stop:price>=t.stop,target=t.side===1?price>=t.target:price<=t.target;let backInside=t.mode==='breakout'&&(t.side===1?price<t.trigger:price>t.trigger),expired=Date.now()-t.added>t.hold*3600000;t.status=stop?'STOP LEVEL REACHED':target?'TARGET REACHED':backInside?'At risk: price returned inside the breakout level':expired?'Review: strategy holding period expired':'Monitoring live price';if(stop||target||backInside||expired)alertUser(`risk:${t.id}:${stop?'stop':target?'target':backInside?'failed':'expired'}`,`${symbol}: ${t.status}`,`Latest ${money(price,t.quote)}. Entry ${money(t.entry,t.quote)}; stop ${money(t.stop,t.quote)}. Review your position.`)}renderTracked()}
function stopLive(){liveGeneration++;for(let s of liveSockets){try{s.disconnect?s.disconnect():s.close()}catch(e){}}liveSockets=[];receivedAt=0;liveSource='Connecting';if($('liveEntryState'))$('liveEntryState').textContent='Waiting for a fresh price update.';}
function applyPrice(ex,symbol,price,sourceTime,source){if(!(price>0&&Number.isFinite(price)))return;let ts=sourceTime||Date.now();if(Date.now()-ts>15000||ts>Date.now()+30000)return;checkTracked(ex,symbol,price,ts);if(chartData?.t.exchange!==ex||chartData.t.symbol!==symbol)return;if(ts<lastSourceAt)return;receivedAt=Date.now();lastSourceAt=ts;liveSource=source;$('livePrice').textContent=money(price,chartData.t.quote);chartData.lastPrice=price;let p=chartData.plan;let state=!p?'No confirmed setup for the selected strategy.':p.side*(price-p.stop)<=0?'Stop level already breached — this entry plan is invalid.':p.side*(price-p.target)>=0?'Target already reached — wait for a new setup.':!p.confirmed?(p.side*(price-p.trigger)>=0?'Live trigger touched — await a completed 1h confirmation.':'Waiting for the entry trigger.'):`Live price is ${(Math.abs(price/p.entry-1)*100).toFixed(2)}% from the reference entry. Confirm your actual fill before sizing.`;$('liveEntryState').textContent=state;if(p&&!p.confirmed&&(p.side===1?price>=p.trigger:price<=p.trigger))alertUser(`trigger:${ex}:${symbol}:${chartData.mode}:${p.trigger}`,`${symbol}: live entry level touched`,'Provisional trigger. Wait for the required candle close; the setup can reverse.');}
function applyCandle(ex,symbol,tf,c,ts){if(!['1h','4h'].includes(tf)||![c.open,c.high,c.low,c.close,c.time,c.volume].every(Number.isFinite)||c.low<=0||c.high<c.close||c.low>c.close)return;applyPrice(ex,symbol,c.close,ts,'Streaming');if(Date.now()-ts>15000)return;for(let t of tracked.filter(t=>t.exchange===ex&&t.symbol===symbol&&t.mode==='cross'&&tf==='4h')){let a=t.history??[];if(a.length&&c.time>a.at(-1).time){let last=a.at(-1);if(last.time+14400000<=Date.now()){let z=a.slice(-200);if(z.length===200){let fast=z.slice(-50).reduce((n,x)=>n+x.close,0)/50,slow=z.reduce((n,x)=>n+x.close,0)/200;if(t.side*(fast-slow)<0)alertUser('cross-invalid:'+t.id+':'+last.time,t.symbol+': crossover trend reversed','The 50/200 SMA trend is now against your tracked position.')}}a.push(c)}else if(a.length&&a.at(-1).time===c.time)a[a.length-1]=c;t.history=a.slice(-330)}if(chartData?.t.exchange!==ex||chartData.t.symbol!==symbol)return;chartData.candleTs??={};if(ts<(chartData.candleTs[tf]??0))return;chartData.candleTs[tf]=ts;let key=tf==='1h'?'allH':'allF',arr=chartData[key],prev=arr.at(-1),isNew=c.time>prev.time;if(c.time<prev.time)return;if(isNew)arr.push(c);else arr[arr.length-1]=c;chartData[key]=arr.slice(-1000);let viewTf=chartData.mode==='scalp'?'1h':'4h';if(viewTf===tf&&tvCandles){tvCandles.update({time:c.time/1000,open:c.open,high:c.high,low:c.low,close:c.close});tvLiveBar=c;tvVolume?.update({time:c.time/1000,value:c.volume,color:c.close>=c.open?'#23866b45':'#d05e6a45'})}if(isNew)refreshClosed();}
function startLive(){stopLive();lastSourceAt=0;let generation=liveGeneration,targets=[...tracked.map(t=>({exchange:t.exchange,symbol:t.symbol})),...(chartData?[chartData.t]:[])];for(let ex of ['delta','shark']){let symbols=[...new Set(targets.filter(t=>t.exchange===ex).map(t=>t.symbol))];if(!symbols.length)continue;if(ex==='delta'){let ws=new WebSocket('wss://public-socket.india.delta.exchange');liveSockets.push(ws);ws.onopen=()=>ws.send(JSON.stringify({type:'subscribe',payload:{channels:[{name:'candlestick_1h',symbols},{name:'candlestick_4h',symbols},{name:'trades',symbols}]}}));ws.onmessage=e=>{if(generation!==liveGeneration)return;try{let d=JSON.parse(e.data);if(d.type==='trades')applyPrice(ex,d.sy,+d.p,+d.ts/1000,'Streaming');if(d.type?.startsWith('candlestick_')){let tf=d.res,time=d.cst?d.cst/1000:Math.floor(d.ts/1000/(SEC[tf]*1000))*SEC[tf]*1000;applyCandle(ex,d.sy,tf,{time,open:+d.o,high:+d.h,low:+d.l,close:+d.c,volume:+d.v},d.ts/1000)}}catch(e){}};ws.onclose=()=>{if(generation===liveGeneration)setTimeout(()=>{if(generation===liveGeneration)startLive()},10000)};}else if(window.io){let s=window.io('https://fawss.sharkexchange.in/',{transports:['websocket'],reconnectionDelay:3000,reconnectionDelayMax:15000});liveSockets.push(s);s.on('connect',()=>s.emit('subscribe',{params:symbols.flatMap(symbol=>['kline_1h','kline_4h','aggTrade'].map(k=>symbol.toLowerCase()+'@'+k))}));s.on('kline',d=>{if(generation!==liveGeneration||!d.k)return;let k=d.k;applyCandle(ex,d.ps??d.s,k.i,{time:+k.t,open:+k.o,high:+k.h,low:+k.l,close:+k.c,volume:+k.v},+d.E)});s.on('aggTrade',d=>{if(generation===liveGeneration)applyPrice(ex,d.s,+d.p,+d.T||+d.E,'Streaming')})}}}
async function refreshClosed(){if(!chartData||closedBusy)return;closedBusy=true;let base=chartData;try{let [h,f,context]=await Promise.all([candles(base.t.exchange,base.t.symbol,'1h',150),candles(base.t.exchange,base.t.symbol,'4h',330),dailyContext(base.t)]);if(chartData!==base)return;let changed=h.at(-1).time!==base.h.at(-1).time||f.at(-1).time!==base.f.at(-1).time;base.h=h;base.f=f;base.d=context.bars;if(changed){base.historyBars=null;invalidateHistory();renderChart();for(let t of tracked.filter(t=>t.symbol===base.t.symbol&&t.exchange===base.t.exchange&&t.mode==='cross')){let closes=f.map(c=>c.close),fast=closes.slice(-50).reduce((a,b)=>a+b)/50,slow=closes.slice(-200).reduce((a,b)=>a+b)/200;if(t.side*(fast-slow)<0)alertUser('cross-risk:'+t.id+':'+f.at(-1).time,t.symbol+': crossover invalidated','The 50/200 SMA trend has reversed against your tracked position.')}}}catch(e){$('chartStatus').textContent='Closed-candle refresh failed. Previous signal is not freshly verified.'}finally{closedBusy=false}}
async function pollFallback(){if(fallbackBusy||!chartData||(liveSource==='Streaming'&&Date.now()-receivedAt<15000))return;fallbackBusy=true;let base=chartData;try{let ex=base.t.exchange,d=unwrap(await fetchJson(ex,ex==='delta'?'/v2/tickers/'+base.t.symbol:'/v1/market/ticker24Hr/'+base.t.symbol));if(chartData===base)applyPrice(ex,base.t.symbol,+(ex==='delta'?d.close:d.c),Date.now(),'Polling fallback (2s)')}catch(e){liveSource='Feed unavailable'}finally{fallbackBusy=false}}
$('enableAlerts').addEventListener('click',async()=>{if(!('Notification' in window)){$('alertStatus').textContent='Browser notifications unavailable; in-page alerts remain active.';return}let p=await Notification.requestPermission();notifyEnabled=p==='granted';$('alertStatus').textContent=notifyEnabled?'Browser alerts enabled while this page stays open.':'In-page alerts active. Browser notification permission was not granted.'});
$('trackSetup').addEventListener('click',()=>{let p=chartData?.plan,entry=+$('actualEntry').value;if(!p||!(entry>0)){$('trackStatus').textContent='Enter your actual entry price first.';return}if(tracked.length>=5){$('trackStatus').textContent='Track up to five entries. Remove one to add another.';return}if(p.side*(entry-p.stop)<=0){$('trackStatus').textContent='Your entry must be on the valid side of the stop.';return}tracked.push({...p,id:String(Date.now()),entry,exchange:chartData.t.exchange,symbol:chartData.t.symbol,quote:chartData.t.quote,added:Date.now(),status:'Waiting for live prices',history:chartData.f.slice(-330)});saveTracked();startLive();$('trackStatus').textContent='Entry tracked on this device. No order has been placed.'});
$('trackedRows').addEventListener('click',e=>{let b=e.target.closest('[data-remove-track]');if(b){tracked.splice(+b.dataset.removeTrack,1);saveTracked();startLive()}});
setInterval(()=>{let age=receivedAt?Math.floor((Date.now()-receivedAt)/1000):null;$('liveStatus').textContent=age===null?'Waiting for live feed':age>15?'STALE · last update '+age+'s ago':`${liveSource} · received ${age}s ago · source lag ${Math.max(0,receivedAt-lastSourceAt).toFixed(0)}ms`;if(tracked.some(t=>!t.updated||Date.now()-t.updated>15000)){$('trackStatus').textContent='Some tracked prices are stale. Risk alerts may be delayed.'}},1000);
setInterval(pollFallback,2000);setInterval(refreshClosed,30000);setInterval(()=>{if($('autoScan').checked&&!$('runStrategy').disabled&&listings.length)runStrategy()},60000);
