let deltaConnected=false,deltaWritable=false,deltaAccount=null,accountBusy=false,reviewId=null,accountLines=[];
function manualPlan(){let entry=+$('manualEntry').value,stop=+$('manualStop').value,target=+$('manualTarget').value,side=+$('manualSide').value;if(![entry,stop,target].every(x=>Number.isFinite(x)&&x>0)||side*(entry-stop)<=0||side*(target-entry)<=0)return null;return {manual:true,mode:'manual',entry,stop,target,side,risk:side*(entry-stop),trigger:entry,confirmed:true,tf:chartData?.mode==='scalp'?'1h':'4h',hold:24,wait:0}}
for(let id of ['manualEntry','manualStop','manualTarget','manualSide','planMode'])$(id).addEventListener('change',()=>{if(chartData){chartData.sizing=null;renderChart();drawAccountLines()}});
$('useLiveEntry').addEventListener('click',()=>{if(!chartData)return;$('manualEntry').value=chartData.lastPrice??chartData.allH.at(-1).close;renderChart();drawAccountLines()});
async function deskRequest(route,body){let r=await fetch('/api/delta-desk/'+route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Delta desk unavailable');return d}
$('connectDelta').addEventListener('click',async()=>{let key=$('deltaKey').value.trim(),secret=$('deltaSecret').value.trim(),trading=$('deltaTrading').checked;$('deltaKey').value='';$('deltaSecret').value='';$('connectDelta').disabled=true;$('deltaStatus').textContent='Verifying your Delta connection…';try{let d=await deskRequest('connect',{key,secret,trading});deltaConnected=d.connected;deltaWritable=d.trading;await refreshDelta()}catch(e){$('deltaStatus').textContent=e.message}finally{$('connectDelta').disabled=false}});
$('disconnectDelta').addEventListener('click',async()=>{try{await deskRequest('disconnect',{});deltaConnected=false;deltaWritable=false;deltaAccount=null;reviewId=null;$('deltaPositions').innerHTML='';$('deltaOrders').innerHTML='';$('deltaFills').innerHTML='';$('deltaStatus').textContent='Disconnected. No further account requests will be made.';drawAccountLines();updateAccountLayout();refreshTicket();renderTradePositions()}catch(e){$('deltaStatus').textContent=e.message}});
const symbolOf=x=>x.product_symbol??x.product?.symbol??('Product '+x.product_id);
function table(headers,rows){return `<div class="desk-scroll"><table class="desk-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">No records returned.</td></tr>`}</tbody></table></div>`}
async function refreshDelta(){if(accountBusy)return;accountBusy=true;try{let d=await deskRequest('account');deltaAccount=d;deltaConnected=true;deltaWritable=d.trading;$('deltaTrading').checked=d.trading;$('deltaStatus').textContent=`Connected · ${d.trading?'Reviewed order actions enabled':'Account viewing only'} · updated ${new Date(d.asOf).toLocaleTimeString()} · connection saved. ${d.errors.join(' ')}`;
$('deltaPositions').innerHTML=d.positions===null?'<h3>Open positions</h3><p>Positions unavailable. Check your broker before trading.</p>':(()=>{let active=d.positions.filter(p=>+p.size!==0);return `<h3>Open positions · ${active.length}</h3>`+(active.length?`<div class="positions-grid">${active.map(p=>{let symbol=symbolOf(p),os=(d.orders??[]).filter(o=>o.product_id===p.product_id&&o.side===(+p.size>0?'sell':'buy')),stops=os.flatMap(o=>o.stop_order_type==='stop_loss_order'&&+o.stop_price>0?[o.stop_price]:+o.bracket_stop_loss_price>0?[o.bracket_stop_loss_price]:[]),targets=os.flatMap(o=>o.stop_order_type==='take_profit_order'&&+o.stop_price>0?[o.stop_price]:+o.bracket_take_profit_price>0?[o.bracket_take_profit_price]:[]),stop=d.orders===null?'Unverified':stops.length?stops.map(x=>money(x,'USD')).join(' / '):'Not shown — check broker',target=targets.length?targets.map(x=>money(x,'USD')).join(' / '):'Not shown — check broker';return `<article class="position-card"><header><div><b>${esc(symbol)}</b><small>${Math.abs(+p.size)} contracts</small></div><span class="side-tag ${+p.size<0?'short':''}">${+p.size>0?'Long':'Short'}</span></header><div class="position-levels"><div><span>Entry</span><strong>${money(p.entry_price,'USD')}</strong></div><div><span>Open P&amp;L</span><strong>${money(p.unrealized_pnl,'USD')}</strong></div><div><span>Stop order</span><strong class="${stops.length?'':'stop-missing'}">${stop}</strong></div><div><span>Target order</span><strong>${target}</strong></div><div><span>Liquidation</span><strong>${money(p.liquidation_price,'USD')}</strong></div></div><div class="position-actions"><button class="chart-link" data-delta-chart="${esc(symbol)}">Chart</button><button class="chart-link" data-delta-protect="${esc(symbol)}" ${!d.trading?'disabled':''}>Set stop / target</button><button class="chart-link" data-delta-close="${esc(symbol)}" ${!d.trading?'disabled':''}>Review close</button></div></article>`}).join('')}</div>`:'<p>No open positions returned by Delta.</p>')})();
$('deltaOrders').innerHTML=d.orders===null?'<p>Orders unavailable. Protection cannot be verified.</p>':table(['Coin','Side / kind','Contracts','Limit / trigger','State','Action'],d.orders.map(o=>`<tr><td>${esc(symbolOf(o))}</td><td>${esc(o.side)} / ${esc(o.stop_order_type??o.order_type)}</td><td>${esc(o.unfilled_size??o.size)}</td><td>${money(o.limit_price,'USD')} / ${money(o.stop_price,'USD')}${o.bracket_stop_loss_price?'<br>Attached stop '+money(o.bracket_stop_loss_price,'USD'):''}${o.bracket_take_profit_price?'<br>Attached target '+money(o.bracket_take_profit_price,'USD'):''}</td><td>${esc(o.state)}</td><td><button class="chart-link" data-delta-cancel="${o.id}" data-coin="${esc(symbolOf(o))}" ${!d.trading?'disabled':''}>Review cancel</button></td></tr>`));
$('deltaFills').innerHTML=d.fills===null?'<p>Fill history unavailable.</p>':table(['Coin','Buy / sell','Executed price','Contracts','Time'],d.fills.map(f=>`<tr><td>${esc(symbolOf(f))}</td><td>${esc(f.side)}</td><td>${money(f.price,'USD')}</td><td>${esc(f.size)}</td><td>${esc(f.created_at??f.time??'—')}</td></tr>`));drawAccountLines();updateAccountLayout();checkAccountProtection('delta',d);refreshTicket();renderTradePositions();}catch(e){$('deltaStatus').textContent=e.message.includes('Connect Delta')?'Not connected. Enter your Delta key and secret above, then click Connect Delta.':'Account not refreshed: '+e.message+' Previously displayed records may be stale.';if(e.message.includes('Connect Delta')){deltaConnected=false;deltaWritable=false;updateAccountLayout()}}finally{accountBusy=false}}
function drawAccountLines(){if(!tvCandles)return;for(let line of accountLines){try{tvCandles.removePriceLine(line)}catch(e){}}accountLines=[];let levels=[];if(chartData?.t.exchange==='delta'&&deltaAccount)for(let p of deltaAccount.positions??[]){if(symbolOf(p)!==chartData.t.symbol||!+p.size)continue;levels.push(['Position entry',+p.entry_price,'#164c96']);for(let o of deltaAccount.orders??[])if(o.product_id===p.product_id&&o.side===(+p.size>0?'sell':'buy')){if(+o.stop_price>0)levels.push([o.stop_order_type==='stop_loss_order'?'Exchange stop':'Exchange target',+o.stop_price,o.stop_order_type==='stop_loss_order'?'#c73540':'#16835b']);if(+o.bracket_stop_loss_price>0)levels.push(['Exchange stop',+o.bracket_stop_loss_price,'#c73540']);if(+o.bracket_take_profit_price>0)levels.push(['Exchange target',+o.bracket_take_profit_price,'#16835b'])}}
 if(chartData?.t.exchange==='shark'&&sharkAccount)for(let p of sharkAccount.positions??[]){if(sharkCoin(p)!==chartData.t.symbol)continue;levels.push(['Position entry',+p.entryPrice,'#164c96']);for(let o of sharkAccount.orders??[])if(sharkCoin(o)===chartData.t.symbol&&o.placeType==='POSITION'){if(o.subType==='STOP_LOSS')levels.push(['Exchange stop',+(o.stopPrice??o.price),'#c73540']);if(o.subType==='TAKE_PROFIT')levels.push(['Exchange target',+(o.stopPrice??o.price),'#16835b'])}}
 for(let [title,price,color] of levels)if(Number.isFinite(price)&&price>0)accountLines.push(tvCandles.createPriceLine({price,title,color,lineWidth:2,lineStyle:0,axisLabelVisible:true}))}
async function reviewAction(body){reviewId=null;$('reviewDetails').innerHTML='';$('reviewStatus').textContent='Validating current exchange state…';$('confirmReview').disabled=true;$('orderReview').showModal();try{let d=await deskRequest('review',body);reviewId=d.id;$('reviewDetails').innerHTML='<dl>'+Object.entries(d.summary).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')+'</dl>';$('reviewStatus').textContent='This sends a real exchange action. Review expires in 60 seconds. Account updates may be delayed; confirm only once.';$('confirmReview').disabled=false}catch(e){$('reviewStatus').textContent=e.message}}
