$('cancelReview').addEventListener('click',()=>{$('orderReview').close();reviewId=null});$('confirmReview').addEventListener('click',async()=>{if(!reviewId)return;let id=reviewId;reviewId=null;$('confirmReview').disabled=true;$('cancelReview').disabled=true;$('reviewStatus').textContent='Sending once to Delta…';try{let d=await deskRequest('submit',{id,confirm:true});$('reviewStatus').textContent=d.note;await refreshDelta()}catch(e){$('reviewStatus').textContent=e.message+' Do not repeat the order until you check its status on Delta.'}finally{$('cancelReview').disabled=false}});
