$('connectShark').addEventListener('click',async()=>{let key=$('sharkDeskKey').value.trim(),secret=$('sharkDeskSecret').value.trim(),trading=$('sharkTrading').checked;$('sharkDeskKey').value='';$('sharkDeskSecret').value='';$('connectShark').disabled=true;$('sharkStatus').textContent='Verifying Shark key…';try{await sharkRequest('connect',{key,secret,trading});sharkConnected=true;await refreshShark()}catch(e){$('sharkStatus').textContent=e.message}finally{$('connectShark').disabled=false}});
