async function refreshShark(){if(sharkBusy)return;sharkBusy=true;try{let d=await sharkRequest('account');sharkAccount=d;sharkConnected=true;sharkWritable=d.trading;$('sharkTrading').checked=d.trading;$('sharkStatus').textContent=`Connected · ${d.trading?'Reviewed order actions enabled':'Account viewing only'} · updated ${new Date(d.asOf).toLocaleTimeString()} · connection saved`;
 $('sharkPositions').innerHTML=`<h3>Open positions · ${d.positions.length}</h3>`+(d.positions.length?`<div class="positions-grid">${d.positions.map(p=>{let symbol=sharkCoin(p),os=d.orders.filter(o=>sharkCoin(o)===symbol&&o.placeType==='POSITION'),stops=os.filter(o=>o.subType==='STOP_LOSS'),targets=os.filter(o=>o.subType==='TAKE_PROFIT');return `<article class="position-card"><header><div><b>${esc(symbol)}</b><small>${esc(p.quantity)} units · ${esc(p.leverage??'—')}×</small></div><span class="side-tag ${p.positionType==='SHORT'?'short':''}">${esc(p.positionType)}</span></header><div class="position-levels"><div><span>Entry</span><strong>${money(p.entryPrice,p.quoteAsset)}</strong></div><div><span>Margin</span><strong>${money(p.marginInMarginAsset??p.margin,p.marginAsset)}</strong></div><div><span>Stop order</span><strong class="${stops.length?'':'stop-missing'}">${stops.length?stops.map(o=>money(o.stopPrice??o.price,p.quoteAsset)).join(' / '):'Not shown — check broker'}</strong></div><div><span>Target order</span><strong>${targets.length?targets.map(o=>money(o.stopPrice??o.price,p.quoteAsset)).join(' / '):'Not shown — check broker'}</strong></div><div><span>Liquidation</span><strong>${money(p.liquidationPrice,p.quoteAsset)}</strong></div></div><div class="position-actions"><button class="chart-link" data-shark-chart="${esc(symbol)}">Chart</button><button class="chart-link" data-shark-protect="${esc(symbol)}" ${!d.trading?'disabled':''}>Set stop / target</button><button class="chart-link" data-shark-close="${esc(symbol)}" ${!d.trading?'disabled':''}>Review close</button></div></article>`}).join('')}</div>`:'<p>No open positions returned by Shark.</p>');
 $('sharkOrders').innerHTML=sharkAccountTable(['Coin','Side / kind','Quantity','Limit / trigger','State','Action'],d.orders,o=>`<tr><td>${esc(sharkCoin(o))}</td><td>${esc(o.side)} · ${esc(o.subType??o.type)}</td><td>${esc(o.orderAmount??o.quantity)}</td><td>${money(o.price,o.quoteAsset)} / ${money(o.stopPrice,o.quoteAsset)}${o.stopLossPrice?'<br>Attached stop '+money(o.stopLossPrice,o.quoteAsset):''}${o.takeProfitPrice?'<br>Attached target '+money(o.takeProfitPrice,o.quoteAsset):''}</td><td>${esc(o.status??'OPEN')}</td><td><button class="chart-link" data-shark-cancel="${esc(o.clientOrderId)}" data-coin="${esc(sharkCoin(o))}" ${!d.trading?'disabled':''}>Review cancel</button></td></tr>`);
 $('sharkFills').innerHTML=sharkAccountTable(['Coin','Side','Price','Quantity','Time'],d.trades,t=>`<tr><td>${esc(sharkCoin(t))}</td><td>${esc(t.side)}</td><td>${money(t.price,t.quoteAsset??'USD')}</td><td>${esc(t.quantity??t.orderAmount)}</td><td>${esc(t.time??t.createdAt??'—')}</td></tr>`);drawAccountLines();updateAccountLayout();checkAccountProtection('shark',d);refreshTicket();renderTradePositions()}catch(e){$('sharkStatus').textContent=e.message.includes('Connect Shark')?'Not connected. Open Connection settings below.':'Account not refreshed: '+e.message+'. Displayed data may be stale.';if(e.message.includes('Connect Shark')){sharkConnected=false;sharkWritable=false;updateAccountLayout()}else{sharkConnected=true}}finally{sharkBusy=false}}
async function reviewSharkAction(body){sharkReviewId=null;$('sharkReviewDetails').innerHTML='';$('sharkReviewStatus').textContent='Checking the exchange account…';$('sharkReviewConfirm').disabled=true;$('sharkReview').showModal();try{let d=await sharkRequest('review',body);sharkReviewId=d.id;$('sharkReviewDetails').innerHTML='<dl>'+Object.entries(d.summary).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')+'</dl>';$('sharkReviewStatus').textContent='Real exchange action. This review expires in 60 seconds. Confirm only once.';$('sharkReviewConfirm').disabled=false}catch(e){$('sharkReviewStatus').textContent=e.message}}
