function checkAccountProtection(ex,d){if(!Array.isArray(d.positions)||!Array.isArray(d.orders))return;for(let p of d.positions){if(ex==='delta'&&!+p.size)continue;let symbol=ex==='delta'?symbolOf(p):sharkCoin(p),stops=d.orders.filter(o=>ex==='delta'?o.product_id===p.product_id&&o.side===(+p.size>0?'sell':'buy')&&(+o.bracket_stop_loss_price>0||o.stop_order_type==='stop_loss_order'&&+o.stop_price>0):sharkCoin(o)===symbol&&o.placeType==='POSITION'&&o.subType==='STOP_LOSS');if(!stops.length)alertUser(`protection:${ex}:${symbol}:${Math.floor(Date.now()/3600000)}`,symbol+' · check stop protection','No stop is visible in the returned open orders. Check your broker or use Set stop / target on My trades. Do not assume this position is protected.')}}

// The short ticket shares the existing exchange review and second-confirmation flow.
let ticketDemo=true,ticketRules=null,ticketRuleToken=0;
const ticketIds=['ticketSide','ticketEntry','ticketStop','ticketTarget'];
function ticketMessage(message,bad=false){$('ticketPreview').textContent=message;$('ticketPreview').classList.toggle('error',bad)}
function syncTicketCoins(){if(ticketDemo)return;let old=$('ticketCoin').value,coins=listings;$('ticketCoin').innerHTML='<option value="">Choose a coin</option>'+coins.map(t=>`<option value="${esc(t.symbol)}">${esc(t.symbol)}</option>`).join('');if(coins.some(t=>t.symbol===old))$('ticketCoin').value=old;else if(coins.length){$('ticketCoin').value=coins.find(t=>t.symbol===$('chartCoin').value)?.symbol??coins[0].symbol;chooseTicketCoin();return}else{$('ticketEntry').value='';$('ticketStop').value='';$('ticketTarget').value='';ticketRules=null}refreshTicket()}
function setTicketMode(demo){ticketDemo=demo;ticketRuleToken++;ticketRules=null;$('simpleTrade').classList.toggle('practice',demo);$('practiceMode').classList.toggle('practice-active',demo);$('realMode').classList.toggle('active',!demo);$('ticketCoin').disabled=demo;$('ticketModeNote').textContent=demo?'DEMO · Example only. No exchange order can be sent.':'REAL TRADE · Balance, size and leverage are calculated for you. Final confirmation is required.';$('ticketAction').textContent=demo?'Simulate trade':$('ticketSide').value==='buy'?'Place trade':'Place trade';$('ticketAmount').value='';document.querySelectorAll('[data-ticket-preset]').forEach(b=>b.classList.remove('active'));$('ticketStatus').textContent='';$('ticketEnable').classList.add('hide');if(demo){$('ticketLeverage').innerHTML='<option value="2">2×</option>';$('ticketCoin').innerHTML='<option value="">Practice example (no coin)</option>';$('ticketSide').value='buy';$('ticketEntry').value='100';$('ticketStop').value='98';$('ticketTarget').value='104';$('ticketPriceNote').textContent='₹100 is a made-up teaching example, not a market quote.'}else{$('ticketCoin').innerHTML='<option value="">Choose a coin</option>';$('ticketEntry').value='';$('ticketStop').value='';$('ticketTarget').value='';$('ticketPriceNote').textContent='Select a coin to see its last listed price; verify the current price before a real order.';syncTicketCoins()}refreshTicket()}
async function chooseTicketCoin(){let token=++ticketRuleToken,t=listings.find(x=>x.symbol===$('ticketCoin').value);ticketRules=null;$('ticketEntry').value=t?.price>0?String(t.price):'';$('ticketStop').value='';$('ticketTarget').value='';$('ticketPriceNote').textContent=t?.price>0?'Listed price '+money(t.price,t.quote)+' · may have moved. Check your entry.':'Price unavailable. Enter a limit entry from the exchange.';$('ticketQuote').textContent=t?.quote??market();$('ticketSizeCurrency').textContent=t?.quote??market();$('ticketAmount').value='';if(t){if($('chartCoin').value!==t.symbol)openChart(t.symbol,mode);refreshOrderBook();$('ticketStatus').textContent='Checking contract limits…';let rules=await loadContract(t);if(token!==ticketRuleToken)return;ticketRules=rules;$('ticketLeverage').innerHTML=rules?rules.choices.map(n=>`<option value="${n}">${n}×</option>`).join(''):'<option value="">Unavailable</option>';$('ticketLeverage').value=rules?(rules.choices.includes(2)?'2':'1'):'';$('ticketStatus').textContent=rules?'Contract rules loaded.':'Contract rules unavailable. Retry the coin selection.'}refreshTicket()}
function ticketFunds(t){if(ticketDemo)return {balance:10000,currency:'INR',note:'Practice balance ₹10,000'};if(!t)return null;let account=t.exchange==='delta'?deltaAccount:sharkAccount;if(!account||!Number.isFinite(account.asOf)||Date.now()-account.asOf>30000)return null;let wallets=account.wallets??[];if(t.exchange==='delta'){let usd=wallets.find(w=>w.asset==='USD');if(usd)return {balance:usd.available,currency:'USD',note:'Available USD balance from account',walletTotal:usd.total,walletCurrency:'USD'};let inr=wallets.find(w=>w.asset==='INR');if(inr)return {balance:inr.available/85,currency:'USD',note:'INR balance converted at Delta India’s published fixed ₹85/USD rate',walletTotal:inr.total,walletCurrency:'INR'};return null}let assets=t.rawContract?.marginAssetsSupported??[],asset=assets.includes(t.quote)?t.quote:null,w=wallets.find(x=>x.asset===asset);return w?{balance:w.available,currency:asset,note:'Available '+asset+' futures wallet balance',marginAsset:asset,walletTotal:w.total,walletCurrency:asset}:null}
function ticketPlan(){let entry=+$('ticketEntry').value,stop=+$('ticketStop').value,target=+$('ticketTarget').value,side=$('ticketSide').value==='buy'?1:-1;if(![entry,stop,target].every(x=>Number.isFinite(x)&&x>0))return {error:'Set the limit price, stop-loss and target.'};if(side*(entry-stop)<=0||side*(target-entry)<=0)return {error:side===1?'For Long, stop goes below entry and target above.':'For Short, stop goes above entry and target below.'};let t=ticketDemo?null:listings.find(x=>x.symbol===$('ticketCoin').value),rules=ticketDemo?null:ticketRules;if(!ticketDemo&&(!t||!rules))return {error:'Choose a coin and wait for contract limits.'};let funds=ticketFunds(t);if(!funds)return {error:'Available margin is unverified. Refresh the connected account below.'};if(!(funds.balance>0))return {error:'No available margin. Check the futures wallet on your exchange.'};let p={entry,stop,target,side,risk:side*(entry-stop),confirmed:true},cost=ticketDemo?.2:Math.max(.2,rules.fee*2+.05),lev=ticketDemo?2:+$('ticketLeverage').value;if(!Number.isInteger(lev)||(!ticketDemo&&!rules.choices.includes(lev)))return {error:'Choose a valid leverage for this contract.'};let amount=+$('ticketAmount').value,v;
if(amount>0){if(!Number.isFinite(amount))return {error:'Enter a valid order value.'};let notional=amount,units=ticketDemo?notional/entry:Math.floor((notional/entry+1e-12)/rules.step)*rules.step;notional=units*entry;let margin=notional/lev,loss=notional*(p.risk/entry+cost/100),buffer=ticketDemo?1:StrategySignals.liquidation(entry,side,lev,rules,cost).buffer;if(!ticketDemo&&(units<rules.minUnits||units>rules.maxUnits||notional<rules.minNotional||notional>rules.maxNotional))return {error:'Order size is outside this contract’s minimum or maximum.'};if(!(margin>0&&margin<=funds.balance)&&!ticketDemo)return {error:'Funds required exceed available margin.'};if(buffer<=p.risk/entry)return {error:'Liquidation could happen before the stop. Lower leverage.'};v={notional,units,margin,loss,leverage:lev,unsafe:false};}else{v=StrategySignals.size(p,funds.balance,.5,cost,lev,rules);if(!v||v.unsafe)return {error:'Auto size is below this contract minimum or liquidation could come before the stop. Enter an order value to check the actual risk, or choose another coin.'}}let profit=v.notional*(side*(target-entry)/entry-cost/100);if(profit<=0)return {error:'The target does not cover estimated costs.'};let quantity=ticketDemo?v.units:Math.floor(v.units/rules.step+1e-8)*rules.step;if(!(quantity>0))return {error:'Order size is below the contract minimum.'};return {p,v,t,rules,quantity,cost,profit,funds}}
function refreshTicket(){if(!$('ticketPreview'))return;let ex=exchange(),connected=ex==='delta'?deltaConnected:sharkConnected;let t=listings.find(x=>x.symbol===$('ticketCoin').value),funds=ticketFunds(t);$('ticketConnection').textContent=ticketDemo?'Demo · no account used':connected?(funds&&Number.isFinite(funds.walletTotal)?'Wallet '+money(funds.walletTotal,funds.walletCurrency)+' · available '+money(funds.balance,funds.currency):'Connected · wallet unavailable'):'Account not connected';$('ticketAvailable').textContent=funds?money(funds.balance,funds.currency):'—';$('ticketRequired').textContent='—';let x=ticketPlan();if(x.error){ticketMessage(x.error,true);return}let {v,quantity,profit,cost}=x,currency=x.funds.currency;$('ticketRequired').textContent=money(v.margin,currency);let riskShare=v.loss/x.funds.balance*100;ticketMessage(`${Number(quantity.toPrecision(8))} ${ticketDemo?'example units':x.t.base+' units'} · ${v.leverage}× leverage · stop loss estimate ${money(v.loss,currency)} (${riskShare.toFixed(2)}% of available funds) · target gain estimate ${money(profit,currency)}. ${riskShare>1?'High risk: over 1% of available funds. Reduce order value or review carefully. ':''}Fees/slippage ${cost.toFixed(2)}% estimated; a gap can lose more.`,riskShare>1)}
