$('ticketAction').addEventListener('click',async()=>{if(!ticketDemo){let ex=exchange(),connected=ex==='delta'?deltaConnected:sharkConnected;if(!connected){$('ticketStatus').textContent='Connect your account first. Your wallet balance and positions will load automatically.';tab('api');$(ex+'Connection').scrollIntoView({block:'start',behavior:'smooth'});return}}let x=ticketPlan();if(x.error){ticketMessage(x.error,true);return}if(ticketDemo){$('ticketStatus').textContent='Practice trade simulated. No order was sent. In a real trade, Place trade opens a confirmation, then you must confirm once more.';return}let ex=exchange(),connected=ex==='delta'?deltaConnected:sharkConnected,writable=ex==='delta'?deltaWritable:sharkWritable;if(!connected){$('ticketStatus').textContent='Connect '+(ex==='delta'?'Delta':'Shark')+' below first, then return here.';$(ex+'Connection').scrollIntoView({block:'start',behavior:'smooth'});return}if(!writable){$('ticketStatus').textContent='Account viewing is enabled. Click Enable reviewed orders to trade.';$('ticketEnable').classList.remove('hide');return}let body={action:'open',symbol:x.t.symbol,side:ex==='delta'?($('ticketSide').value):($('ticketSide').value.toUpperCase()),entry:x.p.entry,stop:x.p.stop,target:x.p.target,leverage:x.v.leverage};if(ex==='delta'){body.contracts=Math.floor(x.quantity/x.rules.step+1e-8);reviewAction(body)}else{body.quantity=Number(x.quantity.toFixed(10));body.marginAsset=x.funds.marginAsset;reviewSharkAction(body)}});
