const tradeWorkspace=document.createElement('div');tradeWorkspace.className='trade-workspace';const chartPanel=$('chartView').querySelector('.chart-panel');chartPanel.before(tradeWorkspace);tradeWorkspace.append(chartPanel);const book=document.createElement('section');book.className='panel orderbook';book.innerHTML='<h3>Order book</h3><p class="book-status" id="bookStatus">Choose a coin.</p><div class="book-head"><span>Price</span><span>Size</span></div><div id="bookAsks"></div><div class="book-mid" id="bookMid">—</div><div id="bookBids"></div>';tradeWorkspace.append(book,$('simpleTrade'));const tradePositions=document.createElement('section');tradePositions.id='tradePositions';tradePositions.className='panel trade-positions';tradePositions.innerHTML='<div class="position-head"><h3>Open positions</h3><p id="tradePositionsStatus">Connect your account to see positions.</p></div><div id="tradePositionsRows"></div>';tradeWorkspace.append(tradePositions);
const extraControls=document.createElement('details');extraControls.className='panel planner-card trade-advanced';extraControls.innerHTML='<summary>Strategy calculator, backtest &amp; tracking</summary>';let manual=$('manualTicket'),plan=$('planSummary'),track=$('trackedRows').closest('details.panel'),planner=$('chartView').querySelector('.planner-grid'),live=$('liveEntryState');live.before(extraControls);extraControls.append(manual,plan,track,planner);
function renderTradePositions(){if(!$('tradePositionsRows'))return;let ex=exchange(),account=ex==='delta'?deltaAccount:sharkAccount,connected=ex==='delta'?deltaConnected:sharkConnected,status=$('tradePositionsStatus');if(!connected){status.textContent='Connect your account in My trades to load wallet and positions.';$('tradePositionsRows').innerHTML='';return}if(!account||!Array.isArray(account.positions)){status.textContent='Positions unavailable. Refresh account or check the exchange.';$('tradePositionsRows').innerHTML='';return}let items=account.positions.filter(p=>ex==='delta'?+p.size!==0:p.positionStatus==='OPEN'&&+p.quantity!==0);status.textContent=items.length+' open · updated '+new Date(account.asOf).toLocaleTimeString()+(Date.now()-account.asOf>30000?' · stale, refresh account':'');if(!items.length){$('tradePositionsRows').innerHTML='<p class="ticket-note">No open positions on this account.</p>';return}let rows=items.map(p=>{let symbol=ex==='delta'?symbolOf(p):sharkCoin(p),q=ex==='delta'?'USD':p.quoteAsset??(symbol.endsWith('INR')?'INR':'USDT'),size=ex==='delta'?+p.size:+p.quantity,side=ex==='delta'?(size>0?'Long':'Short'):p.positionType,entry=ex==='delta'?p.entry_price:p.entryPrice,mark=ex==='delta'?p.mark_price:p.markPrice,margin=ex==='delta'?p.margin:p.margin??p.marginUsed,profit=ex==='delta'?p.unrealized_pnl:p.unrealisedPnl??p.unrealizedPnl,liq=ex==='delta'?p.liquidation_price:p.liquidationPrice,orders=(account.orders??[]).filter(o=>ex==='delta'?o.product_id===p.product_id&&o.side===(size>0?'sell':'buy'):sharkCoin(o)===symbol&&o.placeType==='POSITION'),stop=orders.find(o=>ex==='delta'?o.stop_order_type==='stop_loss_order'||+o.bracket_stop_loss_price>0:o.subType==='STOP_LOSS'),target=orders.find(o=>ex==='delta'?o.stop_order_type==='take_profit_order'||+o.bracket_take_profit_price>0:o.subType==='TAKE_PROFIT'),sl=ex==='delta'?stop?.stop_price??stop?.bracket_stop_loss_price:stop?.stopPrice??stop?.price,tp=ex==='delta'?target?.stop_price??target?.bracket_take_profit_price:target?.stopPrice??target?.price;return `<tr><td><button class="coin-link" data-trade-position="${esc(symbol)}">${esc(symbol)}</button></td><td>${esc(side)} · ${Math.abs(size).toLocaleString()}</td><td>${money(entry,q)}</td><td>${money(mark,q)}</td><td>${sl?money(sl,q):'<span class="negative">No stop shown</span>'} / ${tp?money(tp,q):'—'}</td><td>${money(liq,q)}</td><td>${money(margin,q)}</td><td class="${+profit>=0?'positive':'negative'}">${money(profit,q)}</td><td><button class="chart-link" data-manage-position="${esc(symbol)}">Manage</button></td></tr>`}).join('');$('tradePositionsRows').innerHTML=table(['Coin','Size','Entry','Mark','Stop / target','Liq. price','Margin','Unrealized P&L',''],[rows])}
$('tradePositions').addEventListener('click',async e=>{let chart=e.target.closest('[data-trade-position]'),manage=e.target.closest('[data-manage-position]');if(chart){let symbol=chart.dataset.tradePosition;if(!listings.some(t=>t.symbol===symbol))await loadListings();if(listings.some(t=>t.symbol===symbol))openChart(symbol,mode)}if(manage){tab('api');$(exchange()+'Connection').scrollIntoView({block:'start',behavior:'smooth'})}});$('ticketConnect').addEventListener('click',()=>{tab('api');$(exchange()+'Connection').scrollIntoView({block:'start',behavior:'smooth'})});renderTradePositions();
let bookBest=null,bookBusy=false,bookRequest=0;
async function refreshOrderBook(){if(bookBusy||activeTab!=='chart'||!listings.length)return;let t=listings.find(x=>x.symbol===$('ticketCoin').value)||listings.find(x=>x.symbol===$('chartCoin').value);if(!t)return;bookBusy=true;let id=++bookRequest,symbol=t.symbol,ex=t.exchange;try{let d=unwrap(await fetchJson(ex,ex==='delta'?'/v2/l2orderbook/'+encodeURIComponent(symbol)+'?depth=10':'/v1/market/depth/'+encodeURIComponent(symbol))),asks=ex==='delta'?d.sell:d.a,bids=ex==='delta'?d.buy:d.b;if(!Array.isArray(asks)||!Array.isArray(bids))throw Error('Order book unavailable');if(id!==bookRequest||exchange()!==ex)return;let clean=a=>a.map(o=>Array.isArray(o)?{price:+o[0],size:+o[1]}:{price:+o.price,size:+o.size}).filter(o=>o.price>0&&o.size>=0);asks=clean(asks).sort((a,b)=>a.price-b.price).slice(0,8);bids=clean(bids).sort((a,b)=>b.price-a.price).slice(0,8);bookBest={bid:bids[0]?.price,ask:asks[0]?.price,symbol};let rows=(a,cls)=>a.map(o=>`<div class="book-row ${cls}"><button type="button" data-book-price="${o.price}">${money(o.price,t.quote)}</button><span>${o.size.toLocaleString('en-US',{maximumFractionDigits:4})}</span></div>`).join('');$('bookAsks').innerHTML=rows(asks.slice().reverse(),'ask');$('bookBids').innerHTML=rows(bids,'bid');$('bookMid').textContent=(asks[0]&&bids[0])?`Spread ${money(asks[0].price-bids[0].price,t.quote)}`:'—';$('bookStatus').textContent=symbol+' · snapshot '+new Date().toLocaleTimeString();}catch(e){bookBest=null;$('bookStatus').textContent='Order book unavailable · retrying';$('bookAsks').innerHTML='';$('bookBids').innerHTML=''}finally{bookBusy=false}}
book.addEventListener('click',e=>{let b=e.target.closest('[data-book-price]');if(b&&!ticketDemo){$('ticketEntry').value=b.dataset.bookPrice;refreshTicket()}});$('ticketBest').addEventListener('click',()=>{let price=$('ticketSide').value==='buy'?bookBest?.ask:bookBest?.bid;if(!ticketDemo&&bookBest?.symbol===$('ticketCoin').value&&price){$('ticketEntry').value=price;refreshTicket()}else $('ticketStatus').textContent='Order book price unavailable for this coin.'});
$('ticketLong').addEventListener('click',()=>setTicketSide('buy'));$('ticketShort').addEventListener('click',()=>setTicketSide('sell'));function setTicketSide(side){$('ticketSide').value=side;$('ticketLong').classList.toggle('active',side==='buy');$('ticketShort').classList.toggle('short-active',side==='sell');$('ticketAction').classList.toggle('short',side==='sell');$('ticketAction').textContent=ticketDemo?'Simulate trade':side==='buy'?'Place trade':'Place trade';refreshTicket()}
document.querySelectorAll('[data-ticket-preset]').forEach(b=>b.addEventListener('click',()=>{let t=listings.find(x=>x.symbol===$('ticketCoin').value),funds=ticketFunds(t),lev=ticketDemo?2:+$('ticketLeverage').value;if(!funds||!(lev>0)){$('ticketStatus').textContent='Connect your account and choose a coin first.';return}$('ticketAmount').value=Number((funds.balance*lev*(+b.dataset.ticketPreset)/100).toPrecision(10));document.querySelectorAll('[data-ticket-preset]').forEach(x=>x.classList.toggle('active',x===b));refreshTicket()}));
function syncBrokerFromChart(){if(ticketDemo)return;let symbol=$('chartCoin').value;if($('ticketCoin').value!==symbol&&[...$('ticketCoin').options].some(o=>o.value===symbol)){$('ticketCoin').value=symbol;chooseTicketCoin()}}$('ticketCoin').addEventListener('change',refreshOrderBook);$('chartCoin').addEventListener('change',()=>{syncBrokerFromChart();refreshOrderBook()});setInterval(refreshOrderBook,5000);setTicketMode(false);
